141	        // written to this CTA's OWN scratch slot[0] (no cross-CTA write race).
142	        float part = 0.0f;
143	        for (int rr = tid; rr < sliceH; rr += NT) {
144	            int r = r0 + rr;
145	            if (r > k) { float x = sP[(long)k * sliceH + rr]; part += x * x; }
146	        }
147	        #pragma unroll
148	        for (int off = 16; off > 0; off >>= 1)
149	            part += __shfl_down_sync(0xffffffffu, part, off);
150	        if (lane == 0) sredw[warp] = part;
151	        __syncthreads();
152	        if (tid == 0) {
153	            float s = 0.0f;
154	            for (int w2 = 0; w2 < nwarps; ++w2) s += sredw[w2];
155	            myslot[0] = s;                       // this CTA's tail2 partial
156	        }
157	        // alpha = col_k[k]: the CTA owning row k publishes it into ITS slot[1].
158	        if (k >= r0 && k < r1 && tid == 0) {
159	            int rr = k - r0;
160	            myslot[1] = sP[(long)k * sliceH + rr];
161	        }
162	        MCTA_BARRIER();
163	        // every CTA deterministically sums the G tail2 partials; alpha is the
164	        // value published by whichever slot's owner holds row k.
165	        if (tid == 0) {
166	            float t2 = 0.0f;
167	            for (int gg = 0; gg < G; ++gg) t2 += scr_mat[(long)gg * SCRW + 0];
168	            sbc[0] = t2;
169	            int owner = k / per; if (owner >= G) owner = G - 1;
170	            sbc[1] = scr_mat[(long)owner * SCRW + 1];
171	        }
172	        __syncthreads();
173	        float tail2 = sbc[0];
174	        float alpha = sbc[1];
175	
176	        float beta, tau_k, scale;
177	        if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
178	        else {
179	            float normx = sqrtf(alpha * alpha + tail2);
180	            float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
181	            beta = -sgn * normx;
182	            tau_k = (beta - alpha) / beta;
183	            scale = 1.0f / (alpha - beta);
184	        }
185	
186	        // Write v into sP col k: v[k]=1 (on the owner), v[r>k]=col_k[r]*scale.
187	        for (int rr = tid; rr < sliceH; rr += NT) {
188	            int r = r0 + rr;
189	            if (r > k) sP[(long)k * sliceH + rr] *= scale;     // becomes v[r]
190	            else if (r == k) sP[(long)k * sliceH + rr] = 1.0f; // v[k]=1 (temp; finalized to beta later)
191	        }
192	        __syncthreads();
193	
194	        if (tau_k != 0.0f) {
195	            // ---- phase B: w[c] = sum_{r>=k} v_k[r]*panel[r,c], for all c ----
196	            // Each warp handles a set of columns; reduce over THIS CTA's rows>=k
197	            // into this CTA's OWN slot[2+c] (disjoint -> no cross-CTA write race).
198	            for (int c = warp; c < b; c += nwarps) {
199	                float acc = 0.0f;
200	                for (int rr = lane; rr < sliceH; rr += 32) {
201	                    int r = r0 + rr;
202	                    if (r >= k) acc += sP[(long)k * sliceH + rr] * sP[(long)c * sliceH + rr];
203	                }
204	                #pragma unroll
205	                for (int off = 16; off > 0; off >>= 1)
206	                    acc += __shfl_down_sync(0xffffffffu, acc, off);
207	                if (lane == 0) myslot[2 + c] = acc;       // this CTA's w[c] partial
208	            }
209	            MCTA_BARRIER();
210	            // every CTA deterministically sums the G w[c] partials into SMEM.
211	            for (int c = tid; c < b; c += NT) {
212	                float wc = 0.0f;
213	                for (int gg = 0; gg < G; ++gg) wc += scr_mat[(long)gg * SCRW + 2 + c];
214	                sbc[2 + c] = wc;
215	            }
216	            __syncthreads();
217	
218	            // apply to trailing cols c>k: panel[r,c] -= tau*v[r]*w[c], this CTA's rows
219	            for (int c = k + 1; c < b; ++c) {
220	                float wc = tau_k * sbc[2 + c];
221	                for (int rr = tid; rr < sliceH; rr += NT) {
222	                    int r = r0 + rr;
223	                    if (r >= k) sP[(long)c * sliceH + rr] -= sP[(long)k * sliceH + rr] * wc;
224	                }
225	            }
226	            // CTA 0 builds T column k using w[c<k] (== V[:,c].v_k) just reduced.
227	            // T[a<k,k] = -tau_k * sum_{c<k} T[a,c] * w[c]; T[k,k]=tau_k.
228	            if (g == 0) {
229	                float* Tb = Tbuf + (long)bid * strideTb;
230	                for (int a = tid; a < BLK; a += NT) {
231	                    if (a < k) {
232	                        float s = 0.0f;
233	                        for (int c = 0; c < k; ++c)
234	                            s += Tb[(long)a * strideTk + c * strideTn] * sbc[2 + c];
235	                        Tb[(long)a * strideTk + k * strideTn] = -tau_k * s;
236	                    } else if (a == k) {
237	                        Tb[(long)a * strideTk + k * strideTn] = tau_k;
238	                    } else {
239	                        Tb[(long)a * strideTk + k * strideTn] = 0.0f;
240	                    }
241	                }
242	            }
243	            __syncthreads();
244	        } else {
245	            // tau_k == 0: identity reflector, T column k = e_k*0 except diag 0.
246	            if (g == 0) {
247	                float* Tb = Tbuf + (long)bid * strideTb;
248	                for (int a = tid; a < BLK; a += NT)
249	                    Tb[(long)a * strideTk + k * strideTn] = 0.0f;
250	            }
251	        }
252	
253	        // finalize column k: diag -> beta (or alpha if no refl), already-v below.
254	        if (k >= r0 && k < r1) {
255	            int rr = k - r0;
256	            if (tid == 0) sP[(long)k * sliceH + rr] = (tail2 == 0.0f) ? alpha : beta;
257	        }
258	        if (g == 0 && tid == 0) taub[k] = tau_k;
259	        MCTA_BARRIER();
260	    }
261	
262	    // Write back: this CTA's rows of the panel (H), and V^T for its rows.
263	    // H panel element (r,c): Hb[r*strideHn + c] = sP[c*sliceH + (r-r0)].
264	    for (long idx = tid; idx < (long)sliceH * BLK; idx += NT) {
265	        int rr = idx % sliceH;
266	        int c  = idx / sliceH;
267	        int r  = r0 + rr;
268	        if (c < b) Hb[(long)r * strideHn + c] = sP[(long)c * sliceH + rr];
269	    }
270	    // V^T: Vt[c, r] (global row r => global col offset j+r in Vt's N dim).
271	    // Vt[c,r] = 1 if r==c, panel[r,c] if r>c, else 0. panel here already holds v
272	    // below diag and beta on diag, so re-derive: r==c ->1, r>c -> sP value, else 0.
273	    {
274	        float* Vb = Vtbuf + (long)bid * strideVb;
275	        for (long idx = tid; idx < (long)sliceH * BLK; idx += NT) {
276	            int rr = idx % sliceH;
277	            int c  = idx / sliceH;
278	            int r  = r0 + rr;
279	            float val;
280	            if (r == c) val = 1.0f;
281	            else if (r > c && c < b) val = sP[(long)c * sliceH + rr];
282	            else val = 0.0f;
283	            Vb[(long)c * strideVk + (long)r * strideVn] = val;
284	        }
285	    }
286	    #undef MCTA_BARRIER
287	}
